   await env.DB.prepare('UPDATE source_snapshots SET pending_batch_id=NULL,updated_at=? WHERE project_id=? AND pending_batch_id=?').bind(time,pid,id).run();await audit(env,session.login,'batch.rejected',id,{version,allRejected:true});return json({id,version,status:'rejected',message:'所有候选均已拒绝；来源已解锁，不会创建 PR 或发布。'},201);
