 if(path==='/internal/sources/snapshots'&&request.method==='POST'){const body=JSON.parse(bodyText);if(!Array.isArray(body.items))return fail(400,'invalid-snapshots');const time=now();for(const item of body.items){const id=item.entity?.id;if(!id)continue;const success=item.status==='fetched';const retry=success?0:1;const next=item.nextCheckAt||new Date(Date.now()+(success?168:1)*3600000).toISOString();await env.DB.prepare(`INSERT INTO source_snapshots(project_id,entity_id,last_attempt_at,last_successful_fetch_at,next_check_at,last_fetched_hash,last_published_hash,last_fetched_json,retry_count,failure_message,pending_batch_id,updated_at) VALUES(?,?,?,?,?,?,NULL,?,?,?,NULL,?) ON CONFLICT(project_id,entity_id) DO UPDATE SET last_attempt_at=excluded.last_attempt_at,last_successful_fetch_at=CASE WHEN ?=1 THEN excluded.last_successful_fetch_at ELSE source_snapshots.last_successful_fetch_at END,next_check_at=excluded.next_check_at,last_fetched_hash=CASE WHEN ?=1 THEN excluded.last_fetched_hash ELSE source_snapshots.last_fetched_hash END,last_fetched_json=CASE WHEN ?=1 THEN excluded.last_fetched_json ELSE source_snapshots.last_fetched_json END,retry_count=CASE WHEN ?=1 THEN 0 ELSE source_snapshots.retry_count+1 END,failure_message=excluded.failure_message,updated_at=excluded.updated_at`).bind(pid,id,time,success?time:null,next,item.sourceHash||null,success?JSON.stringify({pages:item.pages||[]}):null,retry,item.failures?.[0]?.message||null,time,success?1:0,success?1:0,success?1:0,success?1:0).run();}return json({saved:body.items.length});}
