  if(!row||row.version!==expectedVersion||!['awaiting-review','notice-incomplete'].includes(row.status)||row.pr_number||row.final_sha||Object.keys(JSON.parse(row.decisions_json||'{}')).length)return fail(409,'batch-not-restructurable','仅允许无审核决定、无 PR 且仍在待审的当前版本重新结构化。');
